extends PanelContainer

signal line_finished

@export var characters_per_second: float = 30.0

var _tween: Tween

@onready var speaker_label: Label = $VBoxContainer/SpeakerLabel
@onready var dialogue_label: RichTextLabel = $VBoxContainer/DialogueLabel
@onready var continue_indicator: Label = $VBoxContainer/ContinueIndicator


func _ready() -> void:
	continue_indicator.visible = false


func _unhandled_input(event: InputEvent) -> void:
	if not is_showing():
		return

	if event.is_action_pressed("advance_dialogue"):
		advance()
		get_viewport().set_input_as_handled()


func show_line(speaker: String, text: String) -> void:
	var clean_speaker := speaker.strip_edges()
	if clean_speaker.is_empty():
		speaker_label.visible = false
	else:
		speaker_label.visible = true
		speaker_label.text = clean_speaker

	dialogue_label.text = text
	dialogue_label.scroll_to_line(0)
	dialogue_label.visible_ratio = 0.0
	set_indicator_visible(false)

	if _tween and _tween.is_running():
		_tween.kill()

	var total_chars := dialogue_label.get_total_character_count()
	if total_chars == 0 or characters_per_second <= 0.0:
		dialogue_label.visible_ratio = 1.0
		set_indicator_visible(true)
		return

	var duration := total_chars / characters_per_second
	_tween = create_tween()
	_tween.tween_property(dialogue_label, "visible_ratio", 1.0, duration)
	_tween.finished.connect(_on_typing_finished)


func advance() -> void:
	if is_typing():
		complete_line()
	else:
		set_indicator_visible(false)
		line_finished.emit()


func complete_line() -> void:
	if _tween and _tween.is_running():
		_tween.kill()
	dialogue_label.visible_ratio = 1.0
	set_indicator_visible(true)


func is_typing() -> bool:
	return _tween != null and _tween.is_running()


func set_indicator_visible(is_visible: bool) -> void:
	continue_indicator.visible = is_visible


func clear() -> void:
	if _tween and _tween.is_running():
		_tween.kill()
	dialogue_label.text = ""
	speaker_label.text = ""
	speaker_label.visible = false
	set_indicator_visible(false)


func is_showing() -> bool:
	return not dialogue_label.text.is_empty()


func _on_typing_finished() -> void:
	set_indicator_visible(true)

class_name CharacterData
extends Resource

@export var display_name: String = ""
@export var name_color: Color = Color.WHITE
@export var expressions: Dictionary = {}

class_name CharacterDisplay
extends TextureRect

@export var dim_color: Color = Color(0.5, 0.5, 0.5, 1.0)
@export var normal_color: Color = Color.WHITE

var character_data: CharacterData

var _move_tween: Tween
var _fade_tween: Tween
var _focus_tween: Tween


func setup(data: CharacterData) -> void:
	character_data = data
	set_expression("neutral")


func set_expression(expression_name: String) -> void:
	if character_data and character_data.expressions.has(expression_name):
		texture = character_data.expressions[expression_name]


func set_focused(is_focused: bool, duration: float = 0.3) -> void:
	if _focus_tween and _focus_tween.is_running():
		_focus_tween.kill()

	var target_color := normal_color if is_focused else dim_color
	_focus_tween = create_tween()
	_focus_tween.tween_property(self, "modulate", target_color, duration)


func move_to(target_pos: Vector2, duration: float = 0.4) -> void:
	if _move_tween and _move_tween.is_running():
		_move_tween.kill()

	_move_tween = create_tween()
	_move_tween.tween_property(self, "position", target_pos, duration)


func fade_in(duration: float = 0.4) -> void:
	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	modulate.a = 0.0
	visible = true
	_fade_tween = create_tween()
	_fade_tween.tween_property(self, "modulate:a", 1.0, duration)


func fade_out(duration: float = 0.4) -> void:
	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(self, "modulate:a", 0.0, duration)
	_fade_tween.finished.connect(func() -> void: visible = false)

class_name CharacterStage
extends Control

const POSITIONS := {
	"left": Vector2(100, 200),
	"center": Vector2(336, 200),
	"right": Vector2(572, 200)
}

@export var character_display_scene: PackedScene = preload("res://story/character_display.tscn")

var _active_characters: Dictionary = {}


func add_character(char_id: String, data: CharacterData, position_name: String = "center") -> CharacterDisplay:
	if _active_characters.has(char_id):
		remove_character(char_id)

	var display: CharacterDisplay = character_display_scene.instantiate() as CharacterDisplay
	add_child(display)
	display.setup(data)

	var target_pos: Vector2 = POSITIONS.get(position_name, POSITIONS["center"])
	display.position = target_pos
	display.fade_in()

	_active_characters[char_id] = display
	return display


func remove_character(char_id: String) -> void:
	if not _active_characters.has(char_id):
		return

	var display: CharacterDisplay = _active_characters[char_id]
	display.fade_out()
	_active_characters.erase(char_id)


func focus_character(active_char_id: String) -> void:
	for id in _active_characters:
		var display: CharacterDisplay = _active_characters[id]
		display.set_focused(id == active_char_id)


func move_character(char_id: String, position_name: String) -> void:
	if not _active_characters.has(char_id):
		return

	var display: CharacterDisplay = _active_characters[char_id]
	var target_pos: Vector2 = POSITIONS.get(position_name, POSITIONS["center"])
	display.move_to(target_pos)


func get_character(char_id: String) -> CharacterDisplay:
	return _active_characters.get(char_id, null)

class_name BackgroundDisplay
extends Control

var _fade_tween: Tween
var _crossfade_tween: Tween

@onready var current_background: TextureRect = $CurrentBackground
@onready var crossfade_background: TextureRect = $CrossfadeBackground
@onready var black_overlay: ColorRect = $BlackOverlay


func _ready() -> void:
	crossfade_background.modulate.a = 0.0
	black_overlay.modulate.a = 0.0


func is_transitioning() -> bool:
	var crossfade_active := _crossfade_tween != null and _crossfade_tween.is_running()
	var fade_active := _fade_tween != null and _fade_tween.is_running()
	return crossfade_active or fade_active


func set_background(texture: Texture2D) -> void:
	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()
	current_background.texture = texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func crossfade_to(new_texture: Texture2D, duration: float = 0.5) -> void:
	if duration <= 0.0:
		set_background(new_texture)
		return

	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()

	crossfade_background.texture = new_texture
	crossfade_background.modulate.a = 0.0

	_crossfade_tween = create_tween()
	_crossfade_tween.tween_property(crossfade_background, "modulate:a", 1.0, duration)
	await _crossfade_tween.finished

	current_background.texture = new_texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func fade_to_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
		black_overlay.modulate.a = 1.0
		return

	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(black_overlay, "modulate:a", 1.0, duration)
	await _fade_tween.finished


func fade_from_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
		black_overlay.modulate.a = 0.0
		return

	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(black_overlay, "modulate:a", 0.0, duration)
	await _fade_tween.finished


func transition_through_black(new_texture: Texture2D, duration: float = 0.5) -> void:
	if duration <= 0.0:
		if _fade_tween and _fade_tween.is_running():
			_fade_tween.kill()
		black_overlay.modulate.a = 0.0
		set_background(new_texture)
		return

	var half_duration := duration * 0.5
	await fade_to_black(half_duration)
	set_background(new_texture)
	await fade_from_black(half_duration)

class_name StoryInterpreter
extends Node

signal story_finished

@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay

var characters_data: Dictionary = {}


func _ready() -> void:
	characters_data["elena"] = preload("res://story/elena.tres")
	characters_data["marco"] = preload("res://story/marco.tres")


func run_story(commands: Array) -> void:
	for command in commands:
		await execute_command(command)
	story_finished.emit()


func execute_command(command: Dictionary) -> void:
	var command_type: String = command.get("type", "")

	match command_type:
		"line":
			var speaker: String = command.get("speaker", "")
			var text: String = command.get("text", "")
			if character_stage and not speaker.is_empty():
				character_stage.focus_character(speaker.to_lower())
			if dialogue_box:
				dialogue_box.show_line(speaker, text)
				await dialogue_box.line_finished
		"background":
			var texture_path: String = command.get("texture", "")
			if not texture_path.is_empty():
				var tex: Texture2D = load(texture_path) as Texture2D
				if tex and background_display:
					background_display.set_background(tex)
		"show":
			var char_id: String = command.get("character", "")
			var pos: String = command.get("position", "center")
			var data: CharacterData = characters_data.get(char_id, null)
			if data and character_stage:
				character_stage.add_character(char_id, data, pos)
		"hide":
			var char_id: String = command.get("character", "")
			if character_stage:
				character_stage.remove_character(char_id)
		"expression":
			var char_id: String = command.get("character", "")
			var expression: String = command.get("expression", "neutral")
			if character_stage:
				var display: CharacterDisplay = character_stage.get_character(char_id)
				if display:
					display.set_expression(expression)
		"wait":
			var duration: float = float(command.get("duration", 1.0))
			if duration > 0.0:
				await get_tree().create_timer(duration).timeout
		_:
			push_warning("Comando sconosciuto: %s" % command_type)

class_name StoryInterpreter
extends Node

signal story_finished

@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay

var characters_data: Dictionary = {}


func _ready() -> void:
