class BuggyNoReset extends "res://story/story_interpreter.gd":
	func execute_command(cmd: Dictionary) -> void:
		if cmd.get("type", "") == "shake":
			var duration: float = float(cmd.get("duration", 0.3))
			if character_stage:
				character_stage.position += Vector2(15.0, 0.0)
				await get_tree().create_timer(duration).timeout
		else:
			await super.execute_command(cmd)


func _run_tests() -> void:
	var tester = instantiate_script("res://story/test_shake.gd")
	if not check("tester_instantiated", tester != null, "Lo script res://story/test_shake.gd deve esistere e compilare senza errori"):
		return

	if not check("has_test_function", has_function(tester, "test_shake_command"), "test_shake.gd deve contenere la funzione test_shake_command"):
		return

	var screen := await instantiate_scene("res://story/story_screen.tscn")
	if not check("screen", screen != null, "story_screen.tscn deve caricarsi correttamente"):
		return

	var stage := screen.get_node_or_null("CharacterStage") as CharacterStage
	var correct_interpreter := screen.get_node_or_null("StoryInterpreter") as StoryInterpreter
	if not check("correct_interp", correct_interpreter != null and stage != null, "StoryInterpreter e CharacterStage devono essere presenti"):
		return

	stage.position = Vector2(0.0, 0.0)
	var res_correct = await tester.test_shake_command(correct_interpreter)
	if not check("promotes_correct", res_correct == true, "I tuoi controlli devono restituire true quando l'interprete esegue il comando shake correttamente"):
		return

	var buggy_1 := BuggyNoAwait.new()
	buggy_1.character_stage = stage
	screen.add_child(buggy_1)
	stage.position = Vector2(0.0, 0.0)
	var res_buggy_1 = await tester.test_shake_command(buggy_1)
	buggy_1.queue_free()
	if not check("rejects_no_await", res_buggy_1 == false, "I tuoi controlli devono restituire false se l'interprete non attende la fine dell'animazione (manca await)"):
		return

	var buggy_2 := BuggyNoReset.new()
	buggy_2.character_stage = stage
	screen.add_child(buggy_2)
	stage.position = Vector2(0.0, 0.0)
	var res_buggy_2 = await tester.test_shake_command(buggy_2)
	buggy_2.queue_free()
	check("rejects_no_reset", res_buggy_2 == false, "I tuoi controlli devono restituire false se l'interprete lascia il palco spostato senza ripristinare la posizione iniziale")

